code.text:
module "alb" { source = "../alb"  vpc_id = var.vpc_id  subnets = var.public_subnets }
module "db"  { source = "../rds"  vpc_id = var.vpc_id  subnets = var.private_subnets }
module "ecs" {
  source           = "../ecs-service"
  target_group_arn = module.alb.target_group_arn
  db_endpoint      = module.db.endpoint
}

variable "network" {
  type = object({
    vpc_id             = string
    private_subnet_ids = list(string)
    security_group_ids = list(string)
  })
}
resource "aws_ecs_service" "this" {
  network_configuration {
    subnets         = var.network.private_subnet_ids
    security_groups = var.network.security_group_ids
  }
}
